"""Half-open integer interval utilities."""


def merge(intervals):
    """Merge overlapping and touching intervals; returns sorted list of tuples."""
    pairs = [(a, b) for a, b in intervals if a < b]
    if not pairs:
        return []
    pairs.sort()
    out = [list(pairs[0])]
    for s, e in pairs[1:]:
        if s <= out[-1][1]:
            if e > out[-1][1]:
                out[-1][1] = e
        else:
            out.append([s, e])
    return [(s, e) for s, e in out]


def free_gaps(intervals, window):
    """Maximal sub-ranges of [ws, we) not covered by any interval."""
    ws, we = window
    if ws >= we:
        return []
    clipped = []
    for a, b in intervals:
        if a >= b:
            continue
        s, e = max(a, ws), min(b, we)
        if s < e:
            clipped.append((s, e))
    merged = merge(clipped)
    gaps = []
    cur = ws
    for s, e in merged:
        if s > cur:
            gaps.append((cur, s))
        cur = e
    if cur < we:
        gaps.append((cur, we))
    return gaps


def max_overlap(intervals):
    """Largest number of non-empty intervals covering one common point."""
    events = []
    for a, b in intervals:
        if a < b:
            events.append((a, 1))
            events.append((b, -1))
    if not events:
        return 0
    events.sort()
    cur = best = 0
    for _, d in events:
        cur += d
        if cur > best:
            best = cur
    return best

"""LRU cache with per-entry time-to-live."""

import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.clock = clock
        self._data = OrderedDict()  # key -> (value, expiry or None)

    def _expiry(self, ttl):
        if ttl is None:
            return None
        return self.clock() + ttl

    def _purge_expired(self):
        now = self.clock()
        expired = [k for k, (_, e) in self._data.items()
                   if e is not None and now >= e]
        for k in expired:
            del self._data[k]
        return len(expired)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        if key in self._data:
            del self._data[key]
        elif len(self._data) >= self.capacity:
            self._purge_expired()
            if len(self._data) >= self.capacity:
                self._data.popitem(last=False)
        self._data[key] = (value, self._expiry(ttl))

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        value, expiry = entry
        if expiry is not None and self.clock() >= expiry:
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def __contains__(self, key):
        entry = self._data.get(key)
        if entry is None:
            return False
        _, expiry = entry
        if expiry is not None and self.clock() >= expiry:
            del self._data[key]
            return False
        return True

    def __len__(self):
        now = self.clock()
        return sum(1 for (_, e) in self._data.values()
                   if e is None or now < e)

    def keys(self):
        self._purge_expired()
        return list(self._data.keys())

    def evict_expired(self):
        return self._purge_expired()

